test.fill_query:
INSERT INTO json_merge_burst{burst}_vertical{vertical}
SELECT number, concat('{{', arrayStringConcat(arrayMap(i -> concat('"k', toString((intDiv(number, {burst}) * 8 + i) % 256), '":',
    if((number + i) % 3 = 0, concat('"s', toString(number), '"'), toString(number + i))), range(8)), ','), '}}')
FROM numbers(131072)
SETTINGS max_threads = 1, max_insert_threads = 1, max_block_size = 2048, max_insert_block_size = 2048, min_insert_block_size_rows = 2048, min_insert_block_size_bytes = 0

INSERT INTO json_squash_src_burst{burst}
SELECT number, concat('{{', arrayStringConcat(arrayMap(i -> concat('"k', toString((intDiv(number, {burst}) * 8 + i) % 256), '":',
    if((number + i) % 3 = 0, concat('"s', toString(number), '"'), toString(number + i))), range(8)), ','), '}}')
FROM numbers(65536)
SETTINGS max_threads = 1, max_insert_threads = 1, max_block_size = 128, max_insert_block_size = 128, min_insert_block_size_rows = 128, min_insert_block_size_bytes = 0
